#include "Graf.h"

int FpSnps::FindRs(int rs)
{
    int snpNo = -1;
    
    map<int, int>::iterator iter = rsToId.find(rs);
    if (iter != rsToId.end()) {
        snpNo = iter->second;
    }
    
    return snpNo;
}

//
// Set expected p-values for all populations
//
void FpSnps::SetPopulationExpectedPvalues()
{
    int snpNo = 0;
    int numPops = numChkPops;
    
    double popExpPfsums[7];
    double popExpPesums[7];
    double popExpPasums[7];
    
    for (int popId = 0; popId < numPops; popId++) {
        popNumSnps[popId]  = 0;
        popExpPfsums[popId] = 0;
        popExpPfvals[popId] = 0;
        popExpPesums[popId] = 0;
        popExpPevals[popId] = 0;
        popExpPasums[popId] = 0;
        popExpPavals[popId] = 0;
    }
    
    for (snpNo = 0; snpNo < 10000; snpNo++) {
        for (int vetId = 0; vetId < 3; vetId++) {
            double pv  = snps[snpNo].vertexAf[vetId];
            double pfv = snps[snpNo].popAf[0];
            double pev = snps[snpNo].popAf[1];
            double pav = snps[snpNo].popAf[2];
            
            if (pv > 0 && pv < 1 && pfv > 0 && pfv < 1 && pev > 0 && pev < 1 && pav > 0 && pav < 1) {
                double qv  = 1 - pv;
                double qfv = 1 - pfv;
                double qev = 1 - pev;
                double qav = 1 - pav;
                
                double aaPfv = log(pfv) * 2;
                double bbPfv = log(qfv) * 2;
                double abPfv = log(pfv) + log(qfv) + log(2);
                
                double aaPev = log(pev) * 2;
                double bbPev = log(qev) * 2;
                double abPev = log(pev) + log(qev) + log(2);
                
                double aaPav = log(pav) * 2;
                double bbPav = log(qav) * 2;
                double abPav = log(pav) + log(qav) + log(2);
                
                popExpPfsums[vetId] += aaPfv * pv * pv + bbPfv * qv * qv + abPfv * 2 * pv * qv;
                popExpPesums[vetId] += aaPev * pv * pv + bbPev * qv * qv + abPev * 2 * pv * qv;
                popExpPasums[vetId] += aaPav * pv * pv + bbPav * qv * qv + abPav * 2 * pv * qv;
                
                popNumSnps[vetId]++;
            }
        }
    }
    
    for (int vetId = 0; vetId < 3; vetId++) {
        if (popNumSnps[vetId]> 0) {
            popExpPfvals[vetId] = -1 * popExpPfsums[vetId]/popNumSnps[vetId];
            popExpPevals[vetId] = -1 * popExpPesums[vetId]/popNumSnps[vetId];
            popExpPavals[vetId] = -1 * popExpPasums[vetId]/popNumSnps[vetId];
        }
    }
}

void FpSnps::SaveSnps(char* outFile)
{
    FILE *ofp = fopen(outFile, "w");
    if(ofp) {
        fprintf(ofp, "SNP No.\trs#\tchromosome\tposition\tallele1\tallele2\n");
        for (int i = 0; i < numFpSnps; i++) {
            int snpNo = i + 1;
            fprintf(ofp, "%5d\t%10d\t%2d%10d\t%c\t%c\n", snpNo, snps[i].rs, snps[i].chr, snps[i].pos, snps[i].a1, snps[i].a2);
        }
        fclose(ofp);
    }
    else {
        cout << "Couldn't open " << outFile << " for writing!\n";
    }
    cout << "\nSaved " << numFpSnps << " fingerprint SNPs to " << outFile << "\n";
}

FpSnps::~FpSnps()
{
    delete snps;
}

